{
  "events": [
    {
      "key": "academy_next_shift",
      "title": "할당되지 않은 영역",
      "intro": "우이하루가 네가 기록해 둔 확인 순서를 다시 펼친다.",
      "story": "우이하루가 네가 남긴 확인 순서 옆에 아직 담당자가 정해지지 않은 항목들을 하나씩 짚어낸다. 사텐은 돌아갈 골목을 안내해 주겠다고 제안하고, 쿠로코는 통행을 방해받지 않을 경계선을 먼저 확정하자고 말한다. 앞서 기록을 정리했던 너 역시 이번에는 어디까지 책임을 맡을지 답해야 한다.",
      "choices": [
        {
          "index": 1,
          "label": "200골드로 개인 장비를 정비하고 우이하루와 다음 할당량을 확정한다",
          "result": "장비 정비를 마치고 다음 업무 범위를 확정했다. 이동 경로에 대한 구체적인 정보는 아직 부족하다."
        },
        {
          "index": 2,
          "label": "160골드로 안내 표식을 마련하고 사텐과 귀환 경로를 표시한다",
          "result": "귀환 경로에 표식을 남겼다. 다른 구역의 경계선은 여전히 모호한 상태다."
        },
        {
          "index": 3,
          "label": "쿠로코와 협력하여 강한 적이 출몰하는 통로의 경계를 설정한다",
          "result": "위험 통로의 경계를 설정했다. 사텐이 제안한 구체적인 골목 안내는 받지 못했다."
        }
      ]
    },
    {
      "key": "academy_unsealed_list",
      "title": "미결 항목의 세부 사항",
      "intro": "남겨 둔 항목에 돌아갈 곳과 전할 말들이 추가되었다.",
      "story": "우이하루가 네가 접어두지 않은 항목들을 살피며 확인된 내용과 추가 질문이 필요한 사항을 분류한다. 토우마는 짐의 도착지가 아직 비어 있다고 언급하고, 사텐은 먼저 상자를 가리키며 협력을 요청한다. 쿠로코는 이동 전 돌아올 자리도 확보해 달라고 덧붙인다. 이미 기록된 내용이 있어 처음부터 묻지는 않아도 되지만, 모든 인원의 요청을 한꺼번에 처리할 수는 없다.",
      "choices": [
        {
          "index": 1,
          "label": "160골드로 운반 수단을 준비하고 토우마와 짐의 도착지를 확인한다",
          "result": "짐의 도착지를 확인하고 운반 준비를 마쳤다. 사텐의 상자 분류와 쿠로코의 자리 확보는 미뤄졌다."
        },
        {
          "index": 2,
          "label": "사텐과 협력하여 적이 빈번한 납품 구역의 상자를 분류한다",
          "result": "상자 분류를 완료했다. 토우마가 언급한 도착지 정보와 쿠로코의 자리 확보는 아직 해결되지 않았다."
        },
        {
          "index": 3,
          "label": "180골드로 포장재를 마련하고 쿠로코에게 돌아올 자리를 확보한다",
          "result": "돌아올 자리를 확보하고 포장 준비를 끝냈다. 토우마의 도착지 확인과 사텐의 상자 분류는 남은 과제다."
        }
      ]
    }
  ]
}
